import React from "react";
import $ from "./Header.module.css";
import Logo from "../../assets/icon/logo.png";
import { ReactComponent as Location } from "../../assets/icon/location.svg";
import { MainButton } from "../Buttons/MainButton";
import { useDisclosure } from "@mantine/hooks";
import { Modal, FocusTrap } from "@mantine/core";
import { ModalTR } from "../Modals";
import { ModalCloseButton } from "components/Buttons";
import { CONTACTS } from "constants";

export const Header = () => {
  const [isOpen, { open, close }] = useDisclosure(false);
  const handleCloseModal = () => close();
  return (
    <div className={$.header__container}>
      <Modal
        opened={isOpen}
        onClose={close}
        size="auto"
        withCloseButton={false}
        centered
        padding={0}
        transitionProps={{ transition: "pop-bottom-left" }}
      >
        <FocusTrap.InitialFocus />
        <ModalTR onClose={handleCloseModal} />
      </Modal>
      {isOpen && <ModalCloseButton onClickButton={close} />}
      <div className={$.header__company}>
        <img
          src={Logo}
          alt="logo.png"
        />
        <span>
          производитель блок-контейнеров
          <br />и модульных зданий для юр. лиц
        </span>
      </div>
      <div className={$.header__address}>
        <Location width={17} />
        <span>
          АДРЕС: {CONTACTS.addressLine1.toUpperCase()}
          <br />
          {CONTACTS.addressLine2.toUpperCase()}
        </span>
      </div>
      <div className={$.header__contacts}>
        <span>
          {CONTACTS.phone}
          <br />
          {CONTACTS.email}
        </span>
        <MainButton
          onClickButton={() => {
            open();
          }}
        >
          Отправить ТЗ
        </MainButton>
      </div>
    </div>
  );
};
